/**
 * Hero image registry — blur-up (LQIP) placeholders for HeroSection.
 *
 * Generated by scripts/generate-hero-images.mjs, which writes a
 * <slug>.meta.json alongside each variant set at
 * client/public/images/hero/<slug>/. Paste the blurDataURL here whenever a
 * new hero image is generated so <HeroSection slug="..."> can paint an
 * instant placeholder while the real image loads.
 */
export interface HeroImageMeta {
  blurDataURL: string;
}

export const heroImageMeta: Record<string, HeroImageMeta> = {
  tour: {
    blurDataURL:
      "data:image/jpeg;base64,",
  },
  about: {
    blurDataURL:
      "data:image/jpeg;base64,",
  },
  videos: {
    blurDataURL:
      "data:image/jpeg;base64,",
  },
};
